python3 << 'EOF'
import json

# Load current log
log_path = "/agent/guess_log.json"
with open(log_path) as f:
    log = json.load(f)

guesses = log["guesses"]
responses = log["responses"]

print(f"Guesses: {guesses}")
print(f"Responses: {responses}")

# Compute likelihood for secrets 1, 50, 78, 100
for secret in [1, 50, 78, 100, 128]:
    likelihood = 1.0
    correct = 0
    incorrect = 0
    for g, r in zip(guesses, responses):
        if g < secret:
            true_response = "higher"
        elif g > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        if r == true_response:
            likelihood *= 0.7
            correct += 1
        else:
            likelihood *= 0.3
            incorrect += 1

        if g == secret and r != "equals":
            likelihood = 0.0
            correct = 0
            incorrect = 0
            break

    print(f"Secret {secret}: likelihood={likelihood:.6e}, correct={correct}, incorrect={incorrect}")

# Now let's find the secret with maximum likelihood by brute force
N = 128
best_secret = None
best_likelihood = 0.0
for secret in range(1, N+1):
    likelihood = 1.0
    for g, r in zip(guesses, responses):
        if g < secret:
            true_response = "higher"
        elif g > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        if r == true_response:
            likelihood *= 0.7
        else:
            likelihood *= 0.3

        if g == secret and r != "equals":
            likelihood = 0.0
            break

    if likelihood > best_likelihood:
        best_likelihood = likelihood
        best_secret = secret

print(f"\nBest secret: {best_secret} with likelihood {best_likelihood:.6e}")

# Find all secrets with this likelihood
best_secrets = []
for secret in range(1, N+1):
    likelihood = 1.0
    for g, r in zip(guesses, responses):
        if g < secret:
            true_response = "higher"
        elif g > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        if r == true_response:
            likelihood *= 0.7
        else:
            likelihood *= 0.3

        if g == secret and r != "equals":
            likelihood = 0.0
            break

    if abs(likelihood - best_likelihood) < 1e-10:
        best_secrets.append(secret)

print(f"Number of best secrets: {len(best_secrets)}")
print(f"Best secrets: {best_secrets[:20]}...")
print(f"Min best secret: {min(best_secrets)}")
print(f"Max best secret: {max(best_secrets)}")

# Submit the minimum best secret
print(f"\nFinal answer: {min(best_secrets)}")
EOF

