#!/usr/bin/env python3
import json
import subprocess
import sys

def load_log():
    GUESS_LOG = "/agent/guess_log.json"
    try:
        with open(GUESS_LOG) as f:
            return json.load(f)
    except FileNotFoundError:
        return {"guesses": [], "responses": [], "guesses_remaining": 8}

def save_log(log):
    with open("/agent/guess_log.json", "w") as f:
        json.dump(log, f, indent=2)

def make_query(guess):
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    output = result.stdout.strip()
    print(f"Query {guess}: {output}")

    log = load_log()
    # Determine response from output
    if "equals" in output:
        response = "equals"
    elif "higher" in output:
        response = "higher"
    else:
        response = "lower"
    return response, output

def find_median(probs):
    """Find the median of the distribution."""
    cumulative = 0
    for i, p in enumerate(probs):
        cumulative += p
        if cumulative >= 0.5:
            return i
    return len(probs) - 1

def update_posterior(probs, query_pos, response):
    """Update the posterior based on the query response."""
    new_probs = [0.0] * len(probs)

    if response == "equals":
        # If we observe "equals", the target is query_pos with probability 1
        new_probs[query_pos] = 1.0
    elif response == "higher":
        # For x > query_pos: P("higher" | x) = 0.7
        # For x < query_pos: P("higher" | x) = 0.3
        # For x == query_pos: P("higher" | x) = 0
        for x in range(len(probs)):
            if x > query_pos:
                new_probs[x] = probs[x] * 0.7
            elif x < query_pos:
                new_probs[x] = probs[x] * 0.3
            else:
                new_probs[x] = 0.0
    elif response == "lower":
        # For x > query_pos: P("lower" | x) = 0.3
        # For x < query_pos: P("lower" | x) = 0.7
        # For x == query_pos: P("lower" | x) = 0
        for x in range(len(probs)):
            if x > query_pos:
                new_probs[x] = probs[x] * 0.3
            elif x < query_pos:
                new_probs[x] = probs[x] * 0.7
            else:
                new_probs[x] = 0.0

    # Normalize
    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]
    return new_probs

def main():
    # Range is 1 to 128, so we have 128 possible values
    # We'll index them as 0 to 127, where index i corresponds to value i+1
    n = 128
    probs = [1.0 / n] * n

    log = load_log()
    guesses_made = len(log["guesses"])

    print(f"Starting with {log['guesses_remaining']} guesses remaining")
    print(f"Already made {guesses_made} guesses")

    for i in range(guesses_made, 8):
        if log["guesses_remaining"] <= 0:
            print("No more guesses remaining!")
            break

        # Find the median of the current posterior
        median_idx = find_median(probs)
        query_value = median_idx + 1  # Convert to 1-indexed

        print(f"\nQuery {i+1}: querying value {query_value}")
        print(f"Current distribution stats: max prob = {max(probs):.6f} at index {probs.index(max(probs))+1}")

        response, output = make_query(query_value)

        # Update the posterior
        probs = update_posterior(probs, median_idx, response)

        print(f"After update, max prob = {max(probs):.6f} at index {probs.index(max(probs))+1}")

    # Find the mode of the posterior
    mode_idx = probs.index(max(probs))
    answer = mode_idx + 1

    print(f"\nFinal answer: {answer}")
    print(f"Final max probability: {max(probs):.6f}")

    return answer

if __name__ == "__main__":
    answer = main()
    print(f"\nSUBMIT: {answer}")
