import random

# Let's implement a noisy binary search strategy
# Target is in [1, 128], we have 8 queries
# Comparisons are correct with 70% probability

# Strategy: Use 3 queries per comparison step (3 steps), leaving 2 queries for refinement
# Actually, let's think about optimal strategy more carefully

# With 8 queries and 128 values, we need to find the target
# Standard binary search gives us 2^8 = 256 capacity, but with noise it's less

# Optimal strategy: use majority voting with repeated comparisons
# If we use 3 queries per step for 3 steps, we can search 2^3 = 8 regions
# But each region has 128/8 = 16 values, and we have 2 remaining queries

# Let me simulate different strategies to see which works best

def simulate_standard_binary_search(target, num_queries=8, noise_rate=0.3):
    low, high = 1, 128
    for _ in range(num_queries):
        if low == high:
            return low
        mid = (low + high) // 2
        # Simulate noisy comparison
        if mid == target:
            return mid
        actual_direction = "higher" if target > mid else "lower"
        if random.random() < noise_rate:
            observed_direction = "lower" if actual_direction == "higher" else "higher"
        else:
            observed_direction = actual_direction

        if observed_direction == "higher":
            low = mid + 1
        else:
            high = mid - 1
    return (low + high) // 2

def simulate_majority_binary_search(target, num_queries=8, noise_rate=0.3):
    low, high = 1, 128
    queries_left = num_queries

    while queries_left > 0 and low < high:
        # Determine how many queries we can use for this comparison
        # We want to use 3 queries per step for majority voting
        queries_per_step = min(3, queries_left)
        queries_left -= queries_per_step

        if queries_per_step == 1:
            # Single query, standard approach
            mid = (low + high) // 2
            if mid == target:
                return mid
            actual_direction = "higher" if target > mid else "lower"
            if random.random() < noise_rate:
                observed_direction = "lower" if actual_direction == "higher" else "higher"
            else:
                observed_direction = actual_direction

            if observed_direction == "higher":
                low = mid + 1
            else:
                high = mid - 1
        else:
            # Multiple queries, use majority voting
            mid = (low + high) // 2
            if mid == target:
                return mid

            votes_higher = 0
            votes_lower = 0
            for _ in range(queries_per_step):
                actual_direction = "higher" if target > mid else "lower"
                if random.random() < noise_rate:
                    observed_direction = "lower" if actual_direction == "higher" else "higher"
                else:
                    observed_direction = actual_direction

                if observed_direction == "higher":
                    votes_higher += 1
                else:
                    votes_lower += 1

            if votes_higher > votes_lower:
                low = mid + 1
            else:
                high = mid - 1

    return (low + high) // 2

# Test both strategies
standard_success = 0
majority_success = 0
num_trials = 1000

for _ in range(num_trials):
    target = random.randint(1, 128)

    # Standard binary search
    result_standard = simulate_standard_binary_search(target)
    if result_standard == target:
        standard_success += 1

    # Majority binary search
    result_majority = simulate_majority_binary_search(target)
    if result_majority == target:
        majority_success += 1

print(f"Standard binary search success rate: {standard_success/num_trials:.3f}")
print(f"Majority binary search success rate: {majority_success/num_trials:.3f}")
