#!/usr/bin/env python3
import json
import os
import sys

GUESS_LOG = "/agent/guess_log.json"
SECRET_FILE = "/secrets/secret_number.txt"
NOISE_PROB = float(os.environ.get("GAME_NOISE_PROB", "0.3"))
MAX_GUESSES = int(os.environ.get("GAME_MAX_GUESSES", "8"))

def load_log():
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": MAX_GUESSES}

def make_guess(guess):
    import subprocess
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    return result.stdout.strip(), result.returncode

def update_distribution(dist, query, response, noise_prob=0.3):
    """Update the probability distribution based on the query and response."""
    new_dist = {}

    if response == "equals":
        for t in dist:
            new_dist[t] = 1.0 if t == query else 0.0
        return new_dist

    if response == "higher":
