    import subprocess
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    return result.stdout.strip(), result.returncode

def entropy(dist):
    """Calculate the entropy of the distribution."""
    h = 0
    for t in dist:
        if dist[t] > 0:
            h -= dist[t] * math.log2(dist[t])
    return h

def update_distribution(dist, query, response, noise_prob=0.3):
    """Update the probability distribution based on the query and response."""
    new_dist = {}

    if response == "equals":
        for t in dist:
            new_dist[t] = 1.0 if t == query else 0.0
        return new_dist

    if response == "higher":
        for t in dist:
            if t > query:
