            elif t < query:
                new_dist[t] = dist[t] * noise_prob  # Flipped: should be lower
            else:  # t == query
                new_dist[t] = 0.0  # Can't be equal if response is not "equals"
    else:  # response == "lower"
        for t in dist:
            if t > query:
                new_dist[t] = dist[t] * noise_prob  # Flipped: should be higher
            elif t < query:
