#!/usr/bin/env python3
import json
import os
import subprocess
import sys

def load_log():
    GUESS_LOG = "/agent/guess_log.json"
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": int(os.environ.get("GAME_MAX_GUESSES", "8"))}

def make_guess(guess):
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    return result.stdout.strip()

def update_beliefs(probs, guess, response, noise_prob=0.3):
    """Update beliefs using Bayesian inference."""
    new_probs = {}
    for t in range(1, 129):
        if t == guess:
            # If target == guess, response should be "equals"
            if response == "equals":
                likelihood = 1.0
            else:
                likelihood = 0.0
        elif t > guess:
            # True response is "higher"
            if response == "higher":
                likelihood = 1.0 - noise_prob  # Correct
            elif response == "lower":
                likelihood = noise_prob  # Flipped
            else:  # response == "equals"
                likelihood = 0.0
        else:  # t < guess
            # True response is "lower"
            if response == "lower":
                likelihood = 1.0 - noise_prob  # Correct
            elif response == "higher":
                likelihood = noise_prob  # Flipped
            else:  # response == "equals"
                likelihood = 0.0

        new_probs[t] = probs.get(t, 0) * likelihood

    # Normalize
    total = sum(new_probs.values())
    if total > 0:
        for t in new_probs:
            new_probs[t] /= total
    else:
        # Uniform prior as fallback
        for t in range(1, 129):
            new_probs[t] = 1.0 / 128

    return new_probs

def choose_guess(probs, guesses_made):
    """Choose the guess that maximizes expected information gain (minimizes entropy)."""
    noise_prob = 0.3

    best_guess = None
    best_expected_entropy = float('inf')

    for g in range(1, 129):
        if g in guesses_made:
            continue

        # Calculate expected entropy after this guess
        expected_entropy = 0

        # Response "equals"
        p_equals = probs.get(g, 0)
        if p_equals > 0:
            post_equals = update_beliefs(probs, g, "equals", noise_prob)
            entropy_equals = -sum(p * __import__('math').log2(p + 1e-10) for p in post_equals.values() if p > 0)
            expected_entropy += p_equals * entropy_equals

        # Response "higher" (when target > g)
        p_higher_true = sum(probs.get(t, 0) for t in range(g+1, 129))
        p_higher = p_higher_true * (1 - noise_prob) + sum(probs.get(t, 0) for t in range(1, g)) * noise_prob
        if p_higher > 0:
            post_higher = update_beliefs(probs, g, "higher", noise_prob)
            entropy_higher = -sum(p * __import__('math').log2(p + 1e-10) for p in post_higher.values() if p > 0)
            expected_entropy += p_higher * entropy_higher

        # Response "lower" (when target < g)
        p_lower_true = sum(probs.get(t, 0) for t in range(1, g))
        p_lower = p_lower_true * (1 - noise_prob) + sum(probs.get(t, 0) for t in range(g+1, 129)) * noise_prob
        if p_lower > 0:
            post_lower = update_beliefs(probs, g, "lower", noise_prob)
            entropy_lower = -sum(p * __import__('math').log2(p + 1e-10) for p in post_lower.values() if p > 0)
            expected_entropy += p_lower * entropy_lower

        if expected_entropy < best_expected_entropy:
            best_expected_entropy = expected_entropy
            best_guess = g

    return best_guess

def main():
    log = load_log()

    # Initialize uniform prior
    probs = {t: 1.0 / 128 for t in range(1, 129)}

    # Update beliefs based on previous guesses
    for guess, response in zip(log["guesses"], log["responses"]):
        probs = update_beliefs(probs, guess, response)

    print(f"Initial state: {log['guesses_remaining']} guesses remaining")
    print(f"Top 5 most likely targets: {sorted(probs, key=probs.get, reverse=True)[:5]}")

    # Make remaining guesses
    while log["guesses_remaining"] > 0:
        # Choose the best guess
        guess = choose_guess(probs, log["guesses"])
        print(f"Guessing {guess}...")

        # Make the guess
        result = make_guess(guess)
        print(f"Result: {result}")

        # Parse the response
        if "equals" in result:
            response = "equals"
        elif "higher" in result:
            response = "higher"
        else:
            response = "lower"

        # Update beliefs
        probs = update_beliefs(probs, guess, response)

        # Update log
        log = load_log()

        print(f"Updated top 5: {sorted(probs, key=probs.get, reverse=True)[:5]}")

        if response == "equals":
            print(f"Found the target: {guess}")
            return guess

    # If we run out of guesses, submit the most likely target
    best_target = max(probs, key=probs.get)
    print(f"Most likely target: {best_target} with probability {probs[best_target]}")
    return best_target

if __name__ == "__main__":
    target = main()
    print(f"Final answer: {target}")
