import json
import os
import math
import sys

def solve():
    log_path = "/agent/guess_log.json"

    if os.path.exists(log_path):
        with open(log_path) as f:
            log = json.load(f)
    else:
        log = {"guesses": [], "responses": [], "guesses_remaining": 8}

    # prior[i] = P(secret = i+1)
    prior = [1.0/128] * 128

    # Apply past observations
    for guess_val, response in zip(log["guesses"], log["responses"]):
        g = guess_val - 1
        if response == "equals":
            for i in range(128):
                prior[i] = 1.0 if i == g else 0.0
            break

        prior[g] = 0
        for i in range(128):
            if i == g:
                continue
            if i < g:
                true_response = "higher"
            else:
                true_response = "lower"

            if true_response == response:
                prior[i] *= 0.7
            else:
                prior[i] *= 0.3

        total = sum(prior)
        if total > 0:
            prior = [p/total for p in prior]

    if max(prior) == 1.0:
        return prior.index(1.0) + 1

    # Bayesian search with entropy-based query selection
    while log["guesses_remaining"] > 0:
        current_entropy = -sum(p * math.log2(p) for p in prior if p > 1e-10)

        best_query = -1
        best_gain = -1

        for g in range(128):
            p_less = sum(prior[:g])
            p_equal = prior[g]
            p_greater = sum(prior[g+1:])

            expected_entropy = 0

            # If we observe "lower":
            p_obs_lower = p_greater * 0.7 + p_less * 0.3
            if p_obs_lower > 1e-10:
                post_lower = []
                for i in range(128):
                    if i == g:
                        post_lower.append(0)
                    elif i < g:
                        post_lower.append(prior[i] * 0.3)
                    else:
                        post_lower.append(prior[i] * 0.7)
                total_lower = sum(post_lower)
                post_lower = [p/total_lower for p in post_lower]
                ent_lower = -sum(p * math.log2(p) for p in post_lower if p > 1e-10)
                expected_entropy += p_obs_lower * ent_lower

            # If we observe "higher":
            p_obs_higher = p_less * 0.7 + p_greater * 0.3
            if p_obs_higher > 1e-10:
                post_higher = []
                for i in range(128):
                    if i == g:
                        post_higher.append(0)
                    elif i < g:
                        post_higher.append(prior[i] * 0.7)
                    else:
                        post_higher.append(prior[i] * 0.3)
                total_higher = sum(post_higher)
                post_higher = [p/total_higher for p in post_higher]
                ent_higher = -sum(p * math.log2(p) for p in post_higher if p > 1e-10)
                expected_entropy += p_obs_higher * ent_higher

            info_gain = current_entropy - expected_entropy
            if info_gain > best_gain:
                best_gain = info_gain
                best_query = g

        query = best_query + 1
        os.system(f"./guess.py {query} 2>&1")

        with open(log_path) as f:
            log = json.load(f)

        guess_val = log["guesses"][-1]
        response = log["responses"][-1]
        g = guess_val - 1

        if response == "equals":
            for i in range(128):
                prior[i] = 1.0 if i == g else 0.0
            break

        prior[g] = 0
        for i in range(128):
            if i == g:
                continue
            if i < g:
                true_response = "higher"
            else:
                true_response = "lower"

            if true_response == response:
                prior[i] *= 0.7
            else:
                prior[i] *= 0.3

        total = sum(prior)
        if total > 0:
            prior = [p/total for p in prior]

    result = max(range(128), key=lambda i: prior[i]) + 1
    print(f"Final answer: {result}")
    return result

solve()
