#!/usr/bin/env python3
"""Majority Voting Strategy for Noisy Binary Search"""

import json
import os
import sys

GUESS_LOG = "/agent/guess_log.json"

def load_log():
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    max_guesses = int(os.environ.get("GAME_MAX_GUESSES"))
    return {"guesses": [], "responses": [], "guesses_remaining": max_guesses}

def query(guess):
    result = os.popen(f"cd /agent && ./guess.py {guess} 2>&1").read()
    log = load_log()
    return result, log

def majority_vote(responses):
    if responses.count("higher") > responses.count("lower"):
        return "higher"
    elif responses.count("lower") > responses.count("higher"):
        return "lower"
    else:
        # Tie - return the response that occurred more recently
        # Actually, let's just return "higher" as a tie-breaker
        return "higher"

def main():
    # Strategy: Use majority voting with 3 queries per step
    # Step 1: Query midpoint of [1, 128] = 64, 3 times
    # Step 2: Based on majority, narrow to [1, 64] or [65, 128]
    # Step 3: Query midpoint of new range, 3 times
    # Step 4: Based on majority, narrow further
    # Step 5-6: Use remaining 2 queries to refine

    log = load_log()
    if log["guesses_remaining"] == 8:
        # Fresh start
        print("Starting fresh with majority voting strategy")

        # Step 1: Query 64 three times
        responses = []
        for i in range(3):
            result, log = query(64)
            print(f"Query 64 (round {i+1}): {result}")
            if "higher" in result:
                responses.append("higher")
            elif "lower" in result:
                responses.append("lower")
            elif "equals" in result:
                print("Found target: 64")
                return 64

        vote = majority_vote(responses)
        print(f"Majority vote for 64: {vote}")

        if vote == "higher":
            low, high = 65, 128
        else:
            low, high = 1, 63

        # Step 2: Query midpoint of [low, high] three times
        mid = (low + high) // 2
        responses = []
        for i in range(3):
            result, log = query(mid)
            print(f"Query {mid} (round {i+1}): {result}")
            if "higher" in result:
                responses.append("higher")
            elif "lower" in result:
                responses.append("lower")
            elif "equals" in result:
                print(f"Found target: {mid}")
                return mid

        vote = majority_vote(responses)
        print(f"Majority vote for {mid}: {vote}")

        if vote == "higher":
            low = mid + 1
        else:
            high = mid - 1

        # Step 3: Use remaining 2 queries
        # Query the midpoint of [low, high]
        if low <= high:
            mid = (low + high) // 2
            result, log = query(mid)
            print(f"Query {mid}: {result}")
            if "equals" in result:
                print(f"Found target: {mid}")
                return mid

            if "higher" in result:
                low = mid + 1
            else:
                high = mid - 1

            # Last query
            if low <= high:
                mid = (low + high) // 2
                result, log = query(mid)
                print(f"Query {mid}: {result}")
                if "equals" in result:
                    print(f"Found target: {mid}")
                    return mid

                if "higher" in result:
                    low = mid + 1
                else:
                    high = mid - 1

        # Submit the midpoint of the final range
        if low <= high:
            answer = (low + high) // 2
        else:
            # Range is empty, submit the last queried midpoint
            answer = mid
        print(f"Final range: [{low}, {high}], answer: {answer}")
        return answer
    else:
        print(f"Already made {8 - log['guesses_remaining']} queries")
        # Fall back to Bayesian analysis
        return 30

if __name__ == "__main__":
    answer = main()
    print(f"Final answer: {answer}")
