#!/usr/bin/env python3
"""
Noisy binary search with probability tracking.
"""
import json
import math
import os
import subprocess
import sys

def load_log():
    if os.path.exists("/agent/guess_log.json"):
        with open("/agent/guess_log.json") as f:
            return json.load(f)
    else:
        max_guesses = int(os.environ.get("GAME_MAX_GUESSES", "8"))
        return {"guesses": [], "responses": [], "guesses_remaining": max_guesses}

def make_guess(guess_val):
    result = subprocess.run(["./guess.py", str(guess_val)], capture_output=True, text=True)
    output = result.stdout.strip()
    print(f"Guessed {guess_val}, got: {output}")

    if "equals" in output:
        return "equals"
    elif "higher" in output:
        return "higher"
    elif "lower" in output:
        return "lower"
    return None

def update_probabilities(probs, query, response):
    """
    Update probability distribution after a query.
    """
    noise_prob = 0.3
    new_probs = [1.0] * len(probs)

    for i in range(len(probs)):
        target = i + 1  # targets are 1-indexed

        if target == query:
            # If target equals query, the true response is "equals"
            if response == "equals":
                new_probs[i] = probs[i] * 1.0
            else:
                new_probs[i] = probs[i] * 0.0
        elif target > query:
            # True response is "higher"
            if response == "higher":
                new_probs[i] = probs[i] * (1 - noise_prob)  # 0.7
            elif response == "lower":
                new_probs[i] = probs[i] * noise_prob  # 0.3
            else:  # equals
                new_probs[i] = probs[i] * 0.0
        elif target < query:
            # True response is "lower"
            if response == "lower":
                new_probs[i] = probs[i] * (1 - noise_prob)  # 0.7
            elif response == "higher":
                new_probs[i] = probs[i] * noise_prob  # 0.3
            else:  # equals
                new_probs[i] = probs[i] * 0.0

    # Normalize
    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]

    return new_probs

def compute_entropy(probs):
    entropy = 0
    for p in probs:
        if p > 0:
            entropy -= p * math.log2(p)
    return entropy

def find_best_query(probs):
    """
    Find the query that maximizes expected information gain.
    """
    noise_prob = 0.3
    best_query = -1
    best_gain = -1

    n = len(probs)
    current_entropy = compute_entropy(probs)

    for query in range(1, n + 1):
        expected_entropy = 0

        for response in ["higher", "lower", "equals"]:
            # Compute probability of each response
            resp_prob = 0
            for i in range(n):
                target = i + 1
                if target == query:
                    if response == "equals":
                        resp_prob += probs[i]
                elif target > query:
                    if response == "higher":
                        resp_prob += probs[i] * (1 - noise_prob)
                    elif response == "lower":
                        resp_prob += probs[i] * noise_prob
                elif target < query:
                    if response == "lower":
                        resp_prob += probs[i] * (1 - noise_prob)
                    elif response == "higher":
                        resp_prob += probs[i] * noise_prob

            if resp_prob > 0:
                # Compute entropy after this response
                new_probs = update_probabilities(probs, query, response)
                entropy_after = compute_entropy(new_probs)
                expected_entropy += resp_prob * entropy_after

        info_gain = current_entropy - expected_entropy
        if info_gain > best_gain:
            best_gain = info_gain
            best_query = query

    return best_query, best_gain

def main():
    N = 128
    log = load_log()
    remaining = log["guesses_remaining"]

    print(f"Remaining guesses: {remaining}")
    print(f"Previous guesses: {log['guesses']}")
    print(f"Previous responses: {log['responses']}")

