#!/usr/bin/env python3
"""Noisy binary search with Bayesian updating."""

import json
import os
import subprocess
import math

GUESS_LOG = "/agent/guess_log.json"

def run_guess(guess):
    """Run a guess and return the response."""
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    return result.stdout.strip()

def load_log():
    """Load the guess log."""
    with open(GUESS_LOG) as f:
        return json.load(f)

def entropy(probs):
    """Compute entropy of a probability distribution."""
    return -sum(p * math.log2(p + 1e-12) for p in probs if p > 0)

def update_probs(probs, guess, response, noise_prob=0.3):
    """Update probability distribution based on guess and response."""
    n = len(probs)
    new_probs = [0.0] * n

    for i in range(n):
        # True state: i is the secret number (1-indexed, so secret = i+1)
        secret = i + 1

        if guess < secret:
            true_response = "higher"
        elif guess > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        # P(response | true_response)
        if true_response == response:
            if true_response == "equals":
                p_response_given_true = 1.0  # No noise on equals
            else:
                p_response_given_true = 1.0 - noise_prob  # Correct direction
        else:
            if true_response == "equals":
                p_response_given_true = 0.0  # Can't get non-equals if truly equals
            else:
                p_response_given_true = noise_prob  # Flipped direction

        new_probs[i] = probs[i] * p_response_given_true

    # Normalize
    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]
    else:
        # Uniform fallback
        new_probs = [1.0 / n] * n

    return new_probs

def expected_entropy_reduction(probs, guess, noise_prob=0.3):
    """Compute expected entropy reduction for a given guess."""
    n = len(probs)
    current_entropy = entropy(probs)

    expected_new_entropy = 0.0

    for response in ["higher", "lower", "equals"]:
        # Compute probability of each response
        p_response = 0.0
        for i in range(n):
            secret = i + 1
            if guess < secret:
                true_response = "higher"
            elif guess > secret:
                true_response = "lower"
            else:
                true_response = "equals"

            if true_response == response:
                if true_response == "equals":
                    p_resp = 1.0
                else:
                    p_resp = 1.0 - noise_prob
            else:
                if true_response == "equals":
                    p_resp = 0.0
                else:
                    p_resp = noise_prob

            p_response += probs[i] * p_resp

        if p_response > 0:
            # Compute new distribution
            new_probs = [0.0] * n
            for i in range(n):
                secret = i + 1
                if guess < secret:
                    true_response = "higher"
                elif guess > secret:
                    true_response = "lower"
                else:
                    true_response = "equals"

                if true_response == response:
                    if true_response == "equals":
                        p_resp = 1.0
                    else:
                        p_resp = 1.0 - noise_prob
                else:
                    if true_response == "equals":
                        p_resp = 0.0
                    else:
                        p_resp = noise_prob

                new_probs[i] = probs[i] * p_resp

            total = sum(new_probs)
            if total > 0:
                new_probs = [p / total for p in new_probs]
            expected_new_entropy += p_response * entropy(new_probs)

    return current_entropy - expected_new_entropy

def main():
    # Initialize
    n = 128
    probs = [1.0 / n] * n

    # Load existing log to see where we are
    if os.path.exists(GUESS_LOG):
        log = load_log()
        guesses_made = log["guesses"]
        responses = log["responses"]

        # Replay all previous guesses to update probabilities
        for guess, response in zip(guesses_made, responses):
            probs = update_probs(probs, guess, response)

        guesses_remaining = log["guesses_remaining"]
    else:
        guesses_remaining = 8

    print(f"Starting with {guesses_remaining} guesses remaining")
    print(f"Current most likely target: {probs.index(max(probs)) + 1} with prob {max(probs):.4f}")

    while guesses_remaining > 0:
        # Find the guess that maximizes expected entropy reduction
        best_guess = 1
        best_reduction = -1

        for g in range(1, n + 1):
            reduction = expected_entropy_reduction(probs, g)
            if reduction > best_reduction:
                best_reduction = reduction
                best_guess = g

        print(f"\nQuery {9 - guesses_remaining}: Guess {best_guess} (expected info gain: {best_reduction:.4f} bits)")
        print(f"Top 3 candidates: {sorted(range(n), key=lambda i: -probs[i])[:3]} with probs {[probs[i] for i in sorted(range(n), key=lambda i: -probs[i])[:3]]}")

        # Make the guess
        response_text = run_guess(best_guess)
        print(f"Response: {response_text}")

        # Parse response
        if "equals" in response_text:
            print(f"Found the target: {best_guess}")
            probs = [0.0] * n
            probs[best_guess - 1] = 1.0
            break
        elif "higher" in response_text:
            response = "higher"
        else:
            response = "lower"

        # Update probabilities
        probs = update_probs(probs, best_guess, response)
        guesses_remaining -= 1

        print(f"After update, most likely target: {probs.index(max(probs)) + 1} with prob {max(probs):.4f}")

    # Submit the answer
    answer = probs.index(max(probs)) + 1
    print(f"\nFinal answer: {answer}")

    # Write answer to a file for submission
    with open("/agent/answer.txt", "w") as f:
        f.write(str(answer))

    return answer

if __name__ == "__main__":
    main()
