def make_guess(guess):
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    print(result.stdout)
    if result.returncode != 0:
        print(result.stderr)
    return load_log()

def query_point(priors, q):
    """Calculate the expected information gain of querying point q."""
    # For each possible response, calculate the posterior
    responses = ["higher", "lower", "equals"]

    total_info_gain = 0
    for resp in responses:
        posterior = [0.0] * 129  # index 1 to 128
        if resp == "higher":
            for x in range(1, 129):
                if x > q:
                    posterior[x] = priors[x] * 0.7
                elif x < q:
                    posterior[x] = priors[x] * 0.3
                else:  # x == q
                    posterior[x] = 0
        elif resp == "lower":
            for x in range(1, 129):
                if x < q:
                    posterior[x] = priors[x] * 0.7
                elif x > q:
                    posterior[x] = priors[x] * 0.3
                else:
                    posterior[x] = 0
        elif resp == "equals":
            for x in range(1, 129):
                if x == q:
                    posterior[x] = priors[x] * 1.0
                else:
                    posterior[x] = 0

        # Normalize
        total = sum(posterior[1:])
        if total > 0:
            for x in range(1, 129):
                posterior[x] /= total

        # Calculate probability of this response
        p_resp = sum(posterior[1:]) * total  # This is wrong, let me recalculate
        # Actually, p_resp = sum over x of P(resp|x) * P(x)
        p_resp = 0
        for x in range(1, 129):
            if resp == "higher":
                p_resp += (0.7 if x > q else (0.3 if x < q else 0)) * priors[x]
            elif resp == "lower":
                p_resp += (0.7 if x < q else (0.3 if x > q else 0)) * priors[x]
            elif resp == "equals":
                p_resp += (1.0 if x == q else 0) * priors[x]

        # Entropy of posterior
        H_posterior = 0
        for x in range(1, 129):
            if posterior[x] > 0:
                H_posterior -= posterior[x] * math.log2(posterior[x])

        total_info_gain += p_resp * H_posterior

    # Expected entropy after query
    H_prior = 0
    for x in range(1, 129):
        if priors[x] > 0:
            H_prior -= priors[x] * math.log2(priors[x])

    # Information gain = H_prior - expected H_posterior
    return H_prior - total_info_gain

# Initialize uniform priors
priors = [0.0] * 129
for x in range(1, 129):
    priors[x] = 1.0 / 128

log = load_log()

for step in range(8):
    if log["guesses_remaining"] <= 0:
        break

    # Find the query point that maximizes information gain
    best_q = -1
    best_gain = -1

    for q in range(1, 129):
        gain = query_point(priors, q)
        if gain > best_gain:
            best_gain = gain
            best_q = q

    print(f"Step {step}: Querying {best_q}, expected info gain {best_gain:.4f}")

    # Make the guess
    log = make_guess(best_q)

    # Update priors based on response
    resp = log["responses"][-1]
    print(f"Response: {resp}")

    new_priors = [0.0] * 129
    if resp == "higher":
        for x in range(1, 129):
            if x > best_q:
                new_priors[x] = priors[x] * 0.7
            elif x < best_q:
                new_priors[x] = priors[x] * 0.3
            else:
                new_priors[x] = 0
    elif resp == "lower":
        for x in range(1, 129):
            if x < best_q:
                new_priors[x] = priors[x] * 0.7
            elif x > best_q:
                new_priors[x] = priors[x] * 0.3
            else:
                new_priors[x] = 0
    elif resp == "equals":
        new_priors[best_q] = 1.0
        for x in range(1, 129):
            if x != best_q:
                new_priors[x] = 0

    # Normalize
    total = sum(new_priors[1:])
    if total > 0:
        for x in range(1, 129):
            new_priors[x] /= total

    priors = new_priors

    # Find the most likely number
    best_x = max(range(1, 129), key=lambda x: priors[x])
    print(f"Most likely: {best_x} with probability {priors[best_x]:.4f}")

# After all queries, find the most likely number
best_x = max(range(1, 129), key=lambda x: priors[x])
print(f"\nFinal answer: {best_x}")
