#!/usr/bin/env python3
import json
import os
import subprocess
import sys

GUESS_LOG = "/agent/guess_log.json"
SECRET_RANGE = list(range(1, 129))  # 1 to 128 inclusive
NOISE = 0.3
CORRECT = 0.7

def load_log():
    if os.path.exists(GUESS_LOG):
