            return json.load(f)
    max_guesses = int(os.environ.get("GAME_MAX_GUESSES", "8"))
    return {"guesses": [], "responses": [], "guesses_remaining": max_guesses}

def make_guess(guess):
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    return result.stdout.strip()

def compute_posterior(guesses, responses):
    # Start with uniform prior
    probs = {x: 1.0 for x in SECRET_RANGE}

    for guess, response in zip(guesses, responses):
        new_probs = {x: 0.0 for x in SECRET_RANGE}

        if response == "equals":
            new_probs[guess] = 1.0
            probs = new_probs
            break
        else:
            for x in SECRET_RANGE:
                if response == "higher":
                    if x > guess:
                        new_probs[x] = probs[x] * CORRECT
                    elif x < guess:
                        new_probs[x] = probs[x] * NOISE
                    else:  # x == guess
                        new_probs[x] = 0.0
                elif response == "lower":
                    if x > guess:
                        new_probs[x] = probs[x] * NOISE
                    elif x < guess:
                        new_probs[x] = probs[x] * CORRECT
                    else:  # x == guess
                        new_probs[x] = 0.0

            # Normalize
            total = sum(new_probs.values())
            if total > 0:
                probs = {x: new_probs[x] / total for x in SECRET_RANGE}

    return probs

def find_median(probs):
    # Find the value where cumulative probability is 0.5
    sorted_values = sorted(probs.keys())
    cumulative = 0.0
    for x in sorted_values:
        cumulative += probs[x]
        if cumulative >= 0.5:
            return x
    return sorted_values[-1]

def find_best_query(probs):
    """Find the query that maximizes expected information gain."""
    sorted_values = sorted(probs.keys())
    best_gain = -1
    best_query = sorted_values[len(sorted_values)//2]  # default to median

    for g in sorted_values:
        # Expected entropy before query
        total_prob = sum(probs.values())

        # Probability of "higher" response
        p_higher = sum(probs[x] * CORRECT for x in sorted_values if x > g) + \
                   sum(probs[x] * NOISE for x in sorted_values if x < g)

        # Probability of "lower" response
        p_lower = sum(probs[x] * NOISE for x in sorted_values if x > g) + \
                  sum(probs[x] * CORRECT for x in sorted_values if x < g)

        # Probability of "equals" response
        p_equals = probs.get(g, 0)

        # For simplicity, query the median (this is a good heuristic)
        break

    return find_median(probs)

def play_game():
    while True:
        log = load_log()
        if log["guesses_remaining"] <= 0:
            break

        probs = compute_posterior(log["guesses"], log["responses"])
        guess = find_median(probs)

        print(f"Querying {guess}...")
        output = make_guess(guess)
        print(f"Response: {output}")

        if "equals" in output:
            answer = guess
            print(f"Found exact match: {answer}")
            return answer

    # Final answer is the value with highest posterior probability
    log = load_log()
    probs = compute_posterior(log["guesses"], log["responses"])
    answer = max(probs, key=probs.get)
    print(f"Final answer: {answer}")
    return answer

answer = play_game()
print(f"SUBMIT: {answer}")
