import json
import os

def update_probs(probs, query, response, noise=0.3):
    """Update probability distribution after a query."""
    new_probs = probs.copy()
    if response == "equals":
        new_probs = [0.0] * len(probs)
        new_probs[query - 1] = 1.0
        return new_probs

    for i in range(len(probs)):
        secret_val = i + 1
        if response == "higher":
            if secret_val > query:
                new_probs[i] *= 0.7
            elif secret_val < query:
                new_probs[i] *= 0.3
            else:
                new_probs[i] = 0.0
        elif response == "lower":
            if secret_val > query:
                new_probs[i] *= 0.3
            elif secret_val < query:
                new_probs[i] *= 0.7
            else:
                new_probs[i] = 0.0

    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]

    return new_probs

# Observed data
guesses = [65, 83, 96, 106, 99, 97, 98, 88]
responses = ['higher', 'higher', 'higher', 'lower', 'lower', 'higher', 'lower', 'lower']

probs = [1.0 / 128] * 128

for guess, response in zip(guesses, responses):
    probs = update_probs(probs, guess, response)
