#!/usr/bin/env python3
import json
import os
import math
import subprocess

GUESS_LOG = "/agent/guess_log.json"
HISTORY_FILE = "/agent/history.json"

def load_log():
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": 8}

def load_history():
    if os.path.exists(HISTORY_FILE):
        with open(HISTORY_FILE) as f:
            return json.load(f)
    return {"observations": []}

def save_history(history):
    with open(HISTORY_FILE, "w") as f:
        json.dump(history, f, indent=2)

def update_probs(probs, guess, response):
    n = len(probs)
    new_probs = [0.0] * n

    for s in range(n):
        if response == "equals":
            new_probs[s] = 1.0 if s == guess else 0.0
        elif response == "higher":
            if s > guess:
                new_probs[s] = probs[s] * 0.7
            elif s < guess:
                new_probs[s] = probs[s] * 0.3
            else:
                new_probs[s] = 0.0
        else:
            if s > guess:
                new_probs[s] = probs[s] * 0.3
            elif s < guess:
                new_probs[s] = probs[s] * 0.7
            else:
                new_probs[s] = 0.0

    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]
    return new_probs

def optimal_guess(probs):
    """Find the guess that minimizes expected entropy."""
    n = len(probs)
    best_guess = 0
    best_expected_h = float('inf')

    for g in range(n):
        p_equals = probs[g]
        p_higher = sum(probs[s] * 0.7 for s in range(g + 1, n)) + sum(probs[s] * 0.3 for s in range(g))
        p_lower = sum(probs[s] * 0.3 for s in range(g + 1, n)) + sum(probs[s] * 0.7 for s in range(g))

        expected_h = 0.0

        if p_equals > 1e-10:
            expected_h += p_equals * 0.0

        if p_higher > 1e-10:
            new_probs_higher = [probs[s] * 0.7 if s > g else (probs[s] * 0.3 if s < g else 0.0) for s in range(n)]
            total_h = sum(new_probs_higher)
            new_probs_higher = [p / total_h for p in new_probs_higher]
            h = 0
            for p in new_probs_higher:
                if p > 1e-10:
                    h -= p * math.log2(p)
            expected_h += p_higher * h

        if p_lower > 1e-10:
            new_probs_lower = [probs[s] * 0.3 if s > g else (probs[s] * 0.7 if s < g else 0.0) for s in range(n)]
            total_l = sum(new_probs_lower)
            new_probs_lower = [p / total_l for p in new_probs_lower]
            h = 0
            for p in new_probs_lower:
                if p > 1e-10:
                    h -= p * math.log2(p)
            expected_h += p_lower * h

        if expected_h < best_expected_h:
            best_expected_h = expected_h
            best_guess = g

    return best_guess + 1

def play_game(probs):
    """Play one game, returning the observations and updated probs."""
    log = load_log()

    # Check if we've already played this game (guesses already made)
    if len(log['guesses']) > 0:
        # This game is already in progress or completed
        # Apply the guesses to probs
        for guess, response in zip(log['guesses'], log['responses']):
            probs = update_probs(probs, guess - 1, response)
            if response == "equals":
                return probs, [(guess, response)], True  # Game finished early

        # Continue the game
        for i in range(len(log['guesses']), 8):
            g = optimal_guess(probs)

            result = subprocess.run(['/agent/guess.py', str(g)], capture_output=True, text=True)
            if "equals" in result.stdout:
                response = "equals"
            elif "higher" in result.stdout:
                response = "higher"
            else:
                response = "lower"

            probs = update_probs(probs, g - 1, response)

            if response == "equals":
                return probs, [(g, response)], True

        return probs, [], False  # Game already completed
    else:
        # Play a fresh game
        observations = []
        for i in range(8):
            g = optimal_guess(probs)

            result = subprocess.run(['/agent/guess.py', str(g)], capture_output=True, text=True)
            if "equals" in result.stdout:
                response = "equals"
                print(f"Game: Found {g}!")
            elif "higher" in result.stdout:
                response = "higher"
            else:
                response = "lower"

            observations.append((g, response))
            probs = update_probs(probs, g - 1, response)

            if response == "equals":
                return probs, observations, True

        return probs, observations, False

def main():
    history = load_history()

    # Initialize probs based on history
    probs = [1.0 / 128] * 128
    for obs in history['observations']:
        for guess, response in obs:
            probs = update_probs(probs, guess - 1, response)

    print(f"Current entropy: {-sum(p * math.log2(p) if p > 1e-10 else 0 for p in probs)}")
    max_p = max(probs)
    most_likely = probs.index(max_p) + 1
    print(f"Most likely: {most_likely} (prob {max_p:.4f})")

    # Play multiple games until we're confident
    max_games = 20
    for game_num in range(max_games):
        print(f"\n=== Game {game_num + 1} ===")

        probs, observations, finished_early = play_game(probs)

        if observations:
            history['observations'].append(observations)
            save_history(history)

        if finished_early:
            print("Found the secret!")
            return most_likely

        max_p = max(probs)
        most_likely = probs.index(max_p) + 1
        print(f"After game {game_num + 1}: Most likely {most_likely} (prob {max_p:.4f})")

        if max_p > 0.9:
            print("Confident!")
            return most_likely

        # Reset the game for the next round
        if os.path.exists(GUESS_LOG):
            os.remove(GUESS_LOG)

    # If we're not confident, submit the most likely anyway
    print(f"Not confident. Submitting {most_likely}")
    return most_likely

if __name__ == "__main__":
    answer = main()
    print(f"FINAL ANSWER: {answer}")
