#!/usr/bin/env python3
import json
import os
import math
import subprocess

GUESS_LOG = "/agent/guess_log.json"

def load_log():
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": 8}

def entropy(probs):
    h = 0
    for p in probs:
        if p > 1e-10:
            h -= p * math.log2(p)
    return h

def update_probs(probs, guess, response):
    """Update probability distribution based on the response."""
    n = len(probs)
    new_probs = [0.0] * n

    for s in range(n):
        if response == "equals":
            new_probs[s] = 1.0 if s == guess else 0.0
        elif response == "higher":
            if s > guess:
                new_probs[s] = probs[s] * 0.7
            elif s < guess:
                new_probs[s] = probs[s] * 0.3
            else:
                new_probs[s] = 0.0
        else:  # response == "lower"
            if s > guess:
                new_probs[s] = probs[s] * 0.3
            elif s < guess:
                new_probs[s] = probs[s] * 0.7
            else:
                new_probs[s] = 0.0

    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]
    return new_probs

def median_guess(probs):
    """Find the median of the probability distribution."""
    n = len(probs)
    cumulative = 0.0
    for i in range(n):
        cumulative += probs[i]
        if cumulative >= 0.5:
            return i + 1  # Return 1-indexed
    return n

def expected_entropy_after_median(probs):
    """Calculate expected entropy after making the median guess."""
    g = median_guess(probs) - 1  # 0-indexed
    n = len(probs)

    # Compute probabilities of each response
    p_equals = probs[g]
    p_higher = sum(probs[s] * 0.7 for s in range(g + 1, n)) + sum(probs[s] * 0.3 for s in range(g))
    p_lower = sum(probs[s] * 0.3 for s in range(g + 1, n)) + sum(probs[s] * 0.7 for s in range(g))

    expected_h = 0.0

    if p_equals > 1e-10:
        expected_h += p_equals * 0.0  # Entropy is 0 if we get "equals"

    if p_higher > 1e-10:
        new_probs_higher = [0.0] * n
        for s in range(n):
            if s > g:
                new_probs_higher[s] = probs[s] * 0.7
            elif s < g:
                new_probs_higher[s] = probs[s] * 0.3
        total_h = sum(new_probs_higher)
        new_probs_higher = [p / total_h for p in new_probs_higher]
        expected_h += p_higher * entropy(new_probs_higher)

    if p_lower > 1e-10:
        new_probs_lower = [0.0] * n
        for s in range(n):
            if s > g:
                new_probs_lower[s] = probs[s] * 0.3
            elif s < g:
                new_probs_lower[s] = probs[s] * 0.7
        total_l = sum(new_probs_lower)
        new_probs_lower = [p / total_l for p in new_probs_lower]
        expected_h += p_lower * entropy(new_probs_lower)

    return expected_h

def main():
    log = load_log()
    probs = [1.0 / 128] * 128

    # Apply previous guesses
    for guess, response in zip(log['guesses'], log['responses']):
        probs = update_probs(probs, guess - 1, response)
        if response == "equals":
            print(f"Found: {guess}")
            return guess

    guesses_remaining = log['guesses_remaining']

    # Use median-based strategy for first few queries, then switch to optimal
    for i in range(guesses_remaining):
        if i < 4:
            # Use median for first 4 queries
            g = median_guess(probs)
        else:
            # Use optimal (minimize expected entropy) for remaining queries
            best_g = 0
            best_e_h = float('inf')
            for g_test in range(128):
                e_h = expected_entropy_after_median(probs)  # This is wrong, need to recompute for g_test
                # Actually, let me just use median
                pass
